export function miMap<T, R>(arr: T[], fn: (item: T) => R): R[] {
  return arr.reduce<R[]>((acc, item) => {
    acc.push(fn(item));
    return acc;
  }, []);
}

export function miFiltro<T>(arr: T[], fn: (item: T) => boolean): T[] {
  return arr.reduce<T[]>((acc, item) => {
    if (fn(item)) acc.push(item);
    return acc;
  }, []);
}

// probarMapFiltro la usa el runner: aplica ambas funciones sobre el mismo array.
export function probarMapFiltro(arr: number[]): { mapeado: number[]; filtrado: number[] } {
  return {
    mapeado: miMap(arr, (x) => x * 2),
    filtrado: miFiltro(arr, (x) => x % 2 === 0),
  };
}

