export function deepClone<T>(obj: T): T {
  // Primitivos y null se devuelven tal cual: no tienen nada que copiar.
  if (obj === null || typeof obj !== 'object') return obj;
  if (Array.isArray(obj)) return obj.map((x) => deepClone(x)) as T;
  const copia: Record<string, unknown> = {};
  for (const [clave, valor] of Object.entries(obj)) copia[clave] = deepClone(valor);
  return copia as T;
}

