type ConId = { id: number; [clave: string]: unknown };

export function removerDuplicadosPorId(arr: ConId[]): ConId[] {
  // Un Set de ids vistos: una pasada, O(n), y se queda la primera aparición.
  const vistos = new Set<number>();
  return arr.filter((item) => {
    if (vistos.has(item.id)) return false;
    vistos.add(item.id);
    return true;
  });
}

