  // tu código: usa flatMap
}

kata.solucion:
export function dividirEnPalabras(frases: string[]): string[] {
  // split(/\s+/) con filter(Boolean) evita los vacíos de espacios repetidos.
  return frases.flatMap((frase) => frase.split(/\s+/).filter(Boolean));
}

